(6889978, 1038063, 23484, '<td valign="top">Very nice shot, even with the distractions.</td>', 'Very nice shot, even with the distractions.', '2012-10-24 11:03:26.000000', NULL, 1),
(6889979, 1038162, 47316, '<td valign="top">I like the expressions around you. Certainly lots of distractions in crowded China.</td>', 'I like the expressions around you. Certainly lots of distractions in crowded China.', '2012-10-24 11:03:53.000000', NULL, 1),
(6889982, 1038411, 47316, '<td valign="top">Cool shot. Love the ominous tree and the mists in the background. I certainly see that distracting sign down at the bottom, as for the second, it''s not as obvious.</td>', 'Cool shot. Love the ominous tree and the mists in the background. I certainly see that distracting sign down at the bottom, as for the second, it''s not as obvious.', '2012-10-24 11:04:56.000000', NULL, 1),
(6889983, 1038734, 23484, '<td valign="top">That is excellent.</td>', 'That is excellent.', '2012-10-24 11:05:30.000000', NULL, 1),
(6889984, 1038102, 23484, '<td valign="top">In this case, I think the distractions add to it.</td>', 'In this case, I think the distractions add to it.', '2012-10-24 11:06:15.000000', NULL, 1),
(6889985, 1038761, 47316, '<td valign="top">Hum... I''m not sure what''s going on here. What the subject is and what the distraction is is completely ambiguous. Add to that the lack of title and the fact that this is probably just a photo of  your desk really sends the message that not much effort was put into the shot...</td>', 'Hum... I''m not sure what''s going on here. What the subject is and what the distraction is is completely ambiguous. Add to that the lack of title and the fact that this is probably just a photo of  your desk really sends the message that not much effort was put into the shot...', '2012-10-24 11:06:29.000000', NULL, 1),
(6889987, 1038820, 23484, '<td valign="top">I think those distractions give it character.</td>', 'I think those distractions give it character.', '2012-10-24 11:07:04.000000', NULL, 1),
(6889988, 1038150, 23484, '<td valign="top">Beautiful image.</td>', 'Beautiful image.', '2012-10-24 11:07:38.000000', NULL, 1),
(6889989, 1038434, 23484, '<td valign="top">What a perfect place for those trees.</td>', 'What a perfect place for those trees.', '2012-10-24 11:08:58.000000', NULL, 1),
(6889990, 1038650, 23484, '<td valign="top">I would hate them too.</td>', 'I would hate them too.', '2012-10-24 11:09:47.000000', NULL, 1),
(6889991, 1038677, 47316, '<td valign="top">Definitely get your take on the challenge. I think however the shot just isn''t very interesting.</td>', 'Definitely get your take on the challenge. I think however the shot just isn''t very interesting.', '2012-10-24 11:11:01.000000', NULL, 1),
(6889992, 1038143, 47316, '<td valign="top">This is an interesting image. I don''t really see what''s distracting aside from the shorter flower in the background, as the dead flowers seem just as integral to the photo as the live ones.</td>', 'This is an interesting image. I don''t really see what''s distracting aside from the shorter flower in the background, as the dead flowers seem just as integral to the photo as the live ones.', '2012-10-24 11:13:40.000000', NULL, 1),
(6889993, 1038808, 47316, '<td valign="top">Lighting is nice as is the background. I just think there is TOO much going on here and no message. Why spiderman with a bra and all kinda of other things? Why a title about still life when there is clearly a person in the shot?</td>', 'Lighting is nice as is the background. I just think there is TOO much going on here and no message. Why spiderman with a bra and all kinda of other things? Why a title about still life when there is clearly a person in the shot?', '2012-10-24 11:17:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6889994, 1038106, 47316, '<td valign="top">Beautiful. I love the tones. Distracting elements seem obvious to me.</td>', 'Beautiful. I love the tones. Distracting elements seem obvious to me.', '2012-10-24 11:17:48.000000', NULL, 1),
(6889995, 1038374, 47316, '<td valign="top">I''m not sure what I''m looking at or how it ties in to the title. There are interesting textures here but overall, I just don''t get it.</td>', 'I''m not sure what I''m looking at or how it ties in to the title. There are interesting textures here but overall, I just don''t get it.', '2012-10-24 11:18:45.000000', NULL, 1),
(6889998, 1038798, 47316, '<td valign="top">I guess the motion blur is distracting but I can''t see a second element. Aside from that it is not very clear what he is doing. The angle of his face is strange and really the shot is not that interesting.</td>', 'I guess the motion blur is distracting but I can''t see a second element. Aside from that it is not very clear what he is doing. The angle of his face is strange and really the shot is not that interesting.', '2012-10-24 11:20:57.000000', NULL, 1),
(6890006, 1038713, 23484, '<td valign="top">There is always something to screw up a good shot.</td>', 'There is always something to screw up a good shot.', '2012-10-24 11:24:04.000000', NULL, 1),
(6890009, 1038229, 47316, '<td valign="top">Sorry to say it, the blur an imperfection make the shot. :P</td>', 'Sorry to say it, the blur an imperfection make the shot. :P', '2012-10-24 11:25:06.000000', NULL, 1),
(6890011, 1037805, 23484, '<td valign="top">The sun has a way of ruining many of my shots. Nice.</td>', 'The sun has a way of ruining many of my shots. Nice.', '2012-10-24 11:25:32.000000', NULL, 1),
(6890013, 1038493, 23484, '<td valign="top">I still see you! Cool shot.</td>', 'I still see you! Cool shot.', '2012-10-24 11:26:01.000000', NULL, 1),
(6890015, 1038674, 23484, '<td valign="top">Perfect place for a car. Nice reflection.</td>', 'Perfect place for a car. Nice reflection.', '2012-10-24 11:27:02.000000', NULL, 1),
(6890067, 1038229, 93171, '<td valign="top">Nice picture.  I love the color.  I don''t see 2 distracting elements, though...</td>', 'Nice picture.  I love the color.  I don''t see 2 distracting elements, though...', '2012-10-24 12:32:57.000000', NULL, 1),
(6890073, 1038811, 93171, '<td valign="top">Not voting, but it looks like you have some dust on your sensor.  Or is that the distracting element?</td>', 'Not voting, but it looks like you have some dust on your sensor.  Or is that the distracting element?', '2012-10-24 12:39:18.000000', NULL, 1),
(6890075, 1038769, 49109, '<td valign="top">Not very distracting, but enough to met the challenge. What I like is that the bird itself seems to be somehow distracted. Overall one of the better images in the challenge. Bump.</td>', 'Not very distracting, but enough to met the challenge. What I like is that the bird itself seems to be somehow distracted. Overall one of the better images in the challenge. Bump.', '2012-10-24 12:40:19.000000', NULL, 1),
(6890076, 1038703, 93171, '<td valign="top">Not voting, but THIS is what this challenge is about.  Great job.</td>', 'Not voting, but THIS is what this challenge is about.  Great job.', '2012-10-24 12:41:28.000000', NULL, 1),
(6890077, 1038106, 49109, '<td valign="top">I quite like this, even with the contrail. For my taste the car is not enough of a distraction (or did I overlook another element?) 6</td>', 'I quite like this, even with the contrail. For my taste the car is not enough of a distraction (or did I overlook another element?) 6', '2012-10-24 12:42:37.000000', NULL, 1),
(6890078, 1038677, 93171, '<td valign="top">Hilarious!</td>', 'Hilarious!', '2012-10-24 12:42:39.000000', NULL, 1),
(6890083, 1038661, 49109, '<td valign="top">I only see one distraction and that''s the feeder itself<br/>Seriously, there''s three elements in the image (apart from the sky), there''s no way two of these could be distracting - especially considering that the birds are more in focus than the feeder.</td>', 'I only see one distraction and that''s the feeder itselfSeriously, there''s three elements in the image (apart from the sky), there''s no way two of these could be distracting - especially considering that the birds are more in focus than the feeder.', '2012-10-24 12:47:16.000000', NULL, 1),
(6890085, 1038705, 49109, '<td valign="top">How can there be two distracting elements, when there are only two elements in the image (floor doesn''t count because its in the whole image)</td>', 'How can there be two distracting elements, when there are only two elements in the image (floor doesn''t count because its in the whole image)', '2012-10-24 12:49:29.000000', NULL, 1),
